// Regenerates the data behind the dashboard's dot-matrix world map:
//
//   src/features/overview/worldMask.ts         land/sea grid (2 degree cells)
//   src/features/overview/countryCentroids.ts  one label point per country
//
// Source: Natural Earth (public domain, https://www.naturalearthdata.com), pinned to a release so
// the output is reproducible. The generated files are committed, so building the app never needs
// the network; run this only to change the grid or to update the data:
//
//   node scripts/build-world-data.mjs [cache-directory]
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const RELEASE = "v5.1.2";
const BASE = `https://raw.githubusercontent.com/nvkelso/natural-earth-vector/${RELEASE}/geojson`;
const CELL = 2; // degrees
const WEST = -180;
const NORTH = 84;
const SOUTH = -58; // Antarctica is left out; nothing on the map is reported from there
const SUBSAMPLES = 3; // points per cell side; a cell is land when enough of them are
const LAND_THRESHOLD = 3; // of SUBSAMPLES squared

const here = dirname(fileURLToPath(import.meta.url));
const outDir = resolve(here, "../src/features/overview");
const cacheDir = resolve(process.argv[2] ?? join(tmpdir(), "cipherforge-geo"));

async function load(name) {
  const cached = join(cacheDir, name);
  if (!existsSync(cached)) {
    await mkdir(cacheDir, { recursive: true });
    const response = await fetch(`${BASE}/${name}`);
    if (!response.ok) throw new Error(`Could not download ${name}: HTTP ${response.status}`);
    await writeFile(cached, Buffer.from(await response.arrayBuffer()));
  }
  return JSON.parse(await readFile(cached, "utf8"));
}

/** Every polygon of the geometry as a list of rings (outer ring first, then holes). */
function polygonsOf(geometry) {
  if (geometry.type === "Polygon") return [geometry.coordinates];
  if (geometry.type === "MultiPolygon") return geometry.coordinates;
  return [];
}

function bounds(ring) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const [x, y] of ring) {
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  }
  return { minX, minY, maxX, maxY };
}

function insideRing(x, y, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

function buildMask(land) {
  const polygons = land.features.flatMap((feature) =>
    polygonsOf(feature.geometry).map((rings) => ({ rings, box: bounds(rings[0]) })),
  );
  const columns = Math.round(360 / CELL);
  const rows = Math.round((NORTH - SOUTH) / CELL);

  const isLand = (lon, lat) =>
    polygons.some(({ rings, box }) => {
      if (lon < box.minX || lon > box.maxX || lat < box.minY || lat > box.maxY) return false;
      if (!insideRing(lon, lat, rings[0])) return false;
      return !rings.slice(1).some((hole) => insideRing(lon, lat, hole));
    });

  const lines = [];
  for (let row = 0; row < rows; row += 1) {
    let line = "";
    for (let column = 0; column < columns; column += 1) {
      let hits = 0;
      for (let sy = 0; sy < SUBSAMPLES; sy += 1) {
        for (let sx = 0; sx < SUBSAMPLES; sx += 1) {
          const lon = WEST + (column + (sx + 0.5) / SUBSAMPLES) * CELL;
          const lat = NORTH - (row + (sy + 0.5) / SUBSAMPLES) * CELL;
          if (isLand(lon, lat)) hits += 1;
        }
      }
      line += hits >= LAND_THRESHOLD ? "1" : "0";
    }
    lines.push(line);
  }
  return { columns, rows, lines };
}

function buildCentroids(countries) {
  // Some codes cover several features (Australia and its external territories). Keep the most
  // prominent one: Natural Earth gives bigger places a lower MIN_LABEL.
  const best = new Map();
  for (const { properties } of countries.features) {
    const code = properties.ISO_A2_EH !== "-99" ? properties.ISO_A2_EH : properties.ISO_A2;
    if (!/^[A-Z]{2}$/.test(code)) continue;
    const lon = Number(properties.LABEL_X);
    const lat = Number(properties.LABEL_Y);
    if (!Number.isFinite(lon) || !Number.isFinite(lat)) continue;
    const rank = Number(properties.MIN_LABEL);
    const current = best.get(code);
    if (current === undefined || rank < current.rank) {
      best.set(code, { rank, lon: Math.round(lon * 10) / 10, lat: Math.round(lat * 10) / 10 });
    }
  }
  return [...best.entries()]
    .map(([code, { lon, lat }]) => [code, lon, lat])
    .sort((a, b) => a[0].localeCompare(b[0]));
}

const header = (what) =>
  `// Generated by scripts/build-world-data.mjs from Natural Earth ${RELEASE} (public domain).\n` +
  `// ${what}\n// Do not edit by hand; regenerate with: node scripts/build-world-data.mjs\n\n`;

const [land, countries] = await Promise.all([
  load("ne_110m_land.geojson"),
  load("ne_50m_admin_0_countries.geojson"),
]);

const mask = buildMask(land);
const maskSource =
  header("Land is 1, sea is 0. Rows run north to south, columns west to east.") +
  `export const WORLD_MASK = {\n` +
  `  cellDegrees: ${CELL},\n` +
  `  west: ${WEST},\n` +
  `  north: ${NORTH},\n` +
  `  columns: ${mask.columns},\n` +
  `  rows: [\n${mask.lines.map((line) => `    "${line}",`).join("\n")}\n  ],\n` +
  `} as const;\n`;
await writeFile(join(outDir, "worldMask.ts"), maskSource);

const centroids = buildCentroids(countries);
const centroidSource =
  header("A label point (longitude, latitude) for each country, keyed by ISO 3166-1 alpha-2 code.") +
  `export const COUNTRY_CENTROIDS: Readonly<Record<string, readonly [number, number]>> = {\n` +
  centroids.map(([code, lon, lat]) => `  ${code}: [${lon}, ${lat}],`).join("\n") +
  `\n};\n`;
await writeFile(join(outDir, "countryCentroids.ts"), centroidSource);

const landCells = mask.lines.join("").split("1").length - 1;
console.log(
  `worldMask.ts: ${mask.columns}x${mask.rows} cells, ${landCells} land. ` +
    `countryCentroids.ts: ${centroids.length} countries.`,
);
